  const { issues } = await sdk.sentry.listIssues({ project: "api" });
  const targets = issues.filter(i => i.status === "unresolved" && i.count >= 0);
  const out: any[] = [];
  for (const issue of targets) {
    try {
      const b = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
      out.push({ shortId: issue.shortId, owner: b.authorEmail });
    } catch (e) {
      out.push({ shortId: issue.shortId, owner: null, error: String(e) });
    }
  }
  return { total: issues.length, targets: targets.length, out };
}"}

